*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS20800.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_2);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
    $c.stf.showObj(txb_TotalCnt1, false);
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_STD_CD_GRNT_DD.setValue(vCurDate.substr(0, 6) + "01");
    edt_TO_STD_CD_GRNT_DD.setValue(vCurDate);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "ins_search") {
        dts_ProdList.removeAll();
        dts_FileList.removeAll();
        txb_TotalCnt.setValue("총 0건");
        txb_TotalCnt1.setValue("총 0건");
    } else if (pFg == "ins_searchFileList") {
        dts_FileList.removeAll();
        txb_TotalCnt1.setValue("총 0건");
    }
};



/**
 * 상품목록조회(상단 그리드)
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_Search");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_ProdList);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listFileTargetInquiry" + "&outputMessageId=INS_LIST_FILE_TARGET_INQUIRY" + "&param01=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) + "&param03=" + $c.stf.getObjectValue(chb_ALL) + "&param04=" + $c.stf.getObjectValue(chb_BND) + "&param05=" + $c.stf.getObjectValue(chb_ELSDLS) + "&param06=" + $c.stf.getObjectValue(chb_STKCERT) + "&param07=" + $c.stf.getObjectValue(chb_BENFCERT) + "&param08=" + $c.stf.getObjectValue(chb_SUBSRGHT) + "&param09=" + $c.stf.getObjectValue(chb_DR) + "&param10=" + $c.stf.getObjectValue(chb_CORPBND) + "&param11=" + $c.stf.getObjectValue(chb_CP) + "&param12=" + $c.stf.getObjectValue(chb_CD) + "&param13=" + $c.stf.getObjectValue(chb_STRIP) + "&param14=" + $c.stf.getObjectValue(chb_ISUR) + "&param15=" + $c.stf.getObjectValue(txb_ISU_NM) + "&param16=" + $c.stf.getObjectValue(chb_ETN);
    dts_ProdList.DataID = encodeURI(url);
    dts_ProdList.Reset();
};


/**
 * 파일목록조회(하단 그리드)
 */
scwin.ins_searchFileList = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_searchFileList");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_searchFileList")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_FileList);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listFileUploadInquiry" + "&outputMessageId=LIST_FILE_UPLOAD_INQUIRY" + "&param01=" + dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "STD_CD_APPL_ID") + "&param02=" + dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "KIND") + "&param03=" + dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "ISU_NM");
    dts_FileList.DataID = encodeURI(url);
    dts_FileList.Reset();
};


/**
 * 첨부파일 저장
 */
scwin.ins_SaveFile = function() {
    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_SaveFile")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/FileInfoAction.do?method=processEtcFileUpload" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&queryId=lds.ins.stdcd.update.modifyStdCdCdInfo";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_FileList)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Save.Post();
};


/**
 * 파일추가
 */
scwin.fn_AddFile = function() {
    if (dts_ProdList.getRowPosition() < 1) {
        //alert("선택된 상품이 없습니다.");
        return;
    }
    dts_FileList.insertRow();
    inf_find.open();
    var strFile = inf_find.getValue();
    var strFile_ext = strFile.substring(strFile.length - 3, strFile.length);
    if (strFile_ext == "exe") {
        $c.win.alert("파일업로드 대상 확장자 파일이 아닙니다.");
        $c.cp.removeRow(dts_FileList, dts_FileList.getRowPosition());
        return;
    }
    if (inf_find.getValue() != "") {
        // 데이터 세팅.
        var nRow = dts_FileList.getRowPosition();
        dts_FileList.setCellData(nRow, "STD_CD_APPL_ID", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "STD_CD_APPL_ID"));
        dts_FileList.setCellData(nRow, "KIND", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "KIND"));
        dts_FileList.setCellData(nRow, "ISU_NM", dts_ProdList.getCellData(dts_ProdList.getRowPosition(), "ISU_NM"));

        // 파일정보 세팅.
        dts_FileList.setCellData(nRow, "SAVE_FILE_NM", inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_FileList, dts_FileList.getRowPosition());
    }
};



/**
 * 파일삭제
 */
scwin.fn_DeleteFile = function() {
    if (dts_FileList.getRowPosition() < 1) {
        return;
    }
    $c.cp.removeRow(dts_FileList, dts_FileList.getRowPosition());
};


/**
 * 파일다운로드
 */
scwin.fn_DownloadFile = function(attach_seq) {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_08);
    var nRow = dts_FileList.getRowPosition();
    var sKEY1 = dts_FileList.getCellData(nRow, "STD_CD_APPL_ID");
    var sKEY2 = dts_FileList.getCellData(nRow, "ATTACH_FILE_NO");
    var sTmp = dts_FileList.getCellData(nRow, "KIND");
    var sGubun = "";
    if (sTmp == "발행기관") {
        sGubun = "1";
    } else {
        sGubun = "2";
    }
    location.href = "/filedownload.do?KEY1=" + sKEY1 + "&KEY2=" + sKEY2 + "&GUBUN=" + sGubun;
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "ins_Search") {
        if ($c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) == "") {
            $c.win.alert("표준코드부여 시작일를 입력하세요.");
            edt_FROM_STD_CD_GRNT_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) == "") {
            $c.win.alert("표준코드부여 종료일을 입력하세요.");
            edt_TO_STD_CD_GRNT_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
            return false;
        }

        // 체크된것이 하나도 없으면 전체선택 체크
        scwin.fn_CtrlChb_ALL();
    } else if (pGubun == "ins_SaveFile") {
        if (!$c.cp.isModified(dts_FileList)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }
    }
    return true;
};


/**
 * 채권 ~ 발행기관 체크박스 중 하나라도 체크되었다면 전체선택은 체크 해제.
 * 아무것도 체크되어있지 않다면 전체선택 체크
 */
scwin.fn_CtrlChb_ALL = function() {
    if ($c.stf.getObjectValue(chb_BND) == "N" &&
        $c.stf.getObjectValue(chb_ELSDLS) == "N" &&
        $c.stf.getObjectValue(chb_STKCERT) == "N" &&
        $c.stf.getObjectValue(chb_BENFCERT) == "N" &&
        $c.stf.getObjectValue(chb_SUBSRGHT) == "N" &&
        $c.stf.getObjectValue(chb_DR) == "N" &&
        $c.stf.getObjectValue(chb_CORPBND) == "N" &&
        $c.stf.getObjectValue(chb_CP) == "N" &&
        $c.stf.getObjectValue(chb_CD) == "N" &&
        $c.stf.getObjectValue(chb_STRIP) == "N" &&
        $c.stf.getObjectValue(chb_ISUR) == "N" &&
        $c.stf.getObjectValue(chb_ETN) == "N") {
        $c.stf.setObjectValue(chb_ALL, "Y");
    } else {
        $c.stf.setObjectValue(chb_ALL, "N");
    }
};



/**
 * 전체선택이 체크되면 나머지는 언체크
 */
scwin.fn_CtrlChb_Etc = function() {
    if ($c.stf.getObjectValue(chb_ALL) == "Y") {
        $c.stf.setObjectValue(chb_BND, "N");
        $c.stf.setObjectValue(chb_ELSDLS, "N");
        $c.stf.setObjectValue(chb_STKCERT, "N");
        $c.stf.setObjectValue(chb_BENFCERT, "N");
        $c.stf.setObjectValue(chb_SUBSRGHT, "N");
        $c.stf.setObjectValue(chb_DR, "N");
        $c.stf.setObjectValue(chb_CORPBND, "N");
        $c.stf.setObjectValue(chb_CP, "N");
        $c.stf.setObjectValue(chb_CD, "N");
        $c.stf.setObjectValue(chb_STRIP, "N");
        $c.stf.setObjectValue(chb_ISUR, "N");
        $c.stf.setObjectValue(chb_ETN, "N");
    }
};
scwin.gform_onload = function() {
    scwin.fn_Init();
    txb_ISU_NM.focus();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_ProdList_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_ProdList);
    $c.stf.alert_error(dts_ProdList);
    dts_FileList.removeAll();
};
scwin.dts_ProdList_OnLoadCompleted = function(rowcount) {
    if (dts_ProdList.errorMsg) {
        $c.win.alert(dts_ProdList.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_ProdList);
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    dts_FileList.removeAll();
};
scwin.dts_ProdList_OnRowPosChanged = function(row) {
    if (row > 0) {
        // 첨부파일목록조회
        scwin.ins_searchFileList();
    }
};
scwin.dts_FileList_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_FileList);
    $c.stf.alert_error(dts_FileList);
};
scwin.dts_FileList_OnLoadCompleted = function(rowcount) {
    if (dts_FileList.errorMsg) {
        $c.win.alert(dts_FileList.errorMsg);
    }
    $c.cm.CloseWin(-1, grd_FileList);
    txb_TotalCnt1.setValue("총 " + rowcount + "건");
};
scwin.btn_lineadd_onclick = function() {
    // 파일 추가
    scwin.fn_AddFile();
};
scwin.btn_linedelete_onclick = function() {
    // 파일 추가
    scwin.fn_DeleteFile();
};
scwin.btn_save_onclick = function() {
    // 저장
    scwin.ins_SaveFile();
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_search();
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.grd_FileList_OnDblClick = function(row, colid) {
    if (dts_FileList.getRowStatus(dts_FileList.getRowPosition()) == 0 || dts_FileList.getRowStatus(dts_FileList.getRowPosition()) == 3) {
        scwin.fn_DownloadFile();
    }
};
scwin.img_FROM_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_FROM_STD_CD_GRNT_DD);
};
scwin.img_TO_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_TO_STD_CD_GRNT_DD);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_FileList.getRowPosition(), "filename");
    if (contnId == "input") {
        dts_fileList.setCellData(dts_FileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_FileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_FileList.getRowPosition(), "ATTACH_SEQ", dts_FileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.chb_BND_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_ELSDLS_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_STKCERT_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_BENFCERT_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_SUBSRGHT_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_DR_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_CORPBND_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_CP_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_CD_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_STRIP_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_ISUR_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_ALL();
};
scwin.chb_ALL_onclick = function() {
    // 전체선택 체크박스 제어.
    scwin.fn_CtrlChb_Etc();
};
scwin.txb_ISU_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_ISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.chb_ETN_onclick = function() {
    scwin.fn_CtrlChb_ALL();
};
